```sql
SELECT MIN(fact_id) AS latest_revision, MAX(fact_id) AS first_print, (SELECT value_num FROM facts WHERE subject = 'US_PAYROLLS | US nonfarm payroll employment' AND attribute = 'estimate') AS latest_estimate, (SELECT value_num FROM facts WHERE subject = 'US_PAYROLLS | US nonfarm payroll employment' AND attribute = 'estimate' AND kind = 'new') AS first_estimate, (SELECT value_num FROM facts WHERE subject = 'US_PAYROLLS | US nonfarm payroll employment' AND attribute = 'estimate') - (SELECT value_num FROM facts WHERE subject = 'US_PAYROLLS | US nonfarm payroll employment' AND attribute = 'estimate' AND kind = 'new') AS total_revisions, (SELECT COUNT(*) FROM facts WHERE subject = 'US_PAYROLLS | US nonfarm payroll employment' AND attribute = 'estimate' AND kind = 'revision') AS revision_count FROM facts WHERE subject = 'US_PAYROLLS | US nonfarm payroll employment' AND attribute = 'estimate' GROUP BY period ORDER BY learned_at DESC;
```
